-- Fictional development data. Demo password for every account: ApexGrid2026!
-- bcrypt hashes are generated by pgcrypto and are compatible with bcrypt verifiers.
INSERT INTO users(email,password_hash,full_name,role) VALUES
 ('admin@apexgrid.test',crypt('ApexGrid2026!',gen_salt('bf',12)),'Avery Morgan','ADMIN'),
 ('steward@apexgrid.test',crypt('ApexGrid2026!',gen_salt('bf',12)),'Jordan Lee','STEWARD'),
 ('principal@apexgrid.test',crypt('ApexGrid2026!',gen_salt('bf',12)),'Casey Rivera','PRINCIPAL')
ON CONFLICT(email) DO NOTHING;
INSERT INTO users(email,password_hash,full_name,role)
SELECT format('driver%s@apexgrid.test',lpad(n::text,2,'0')),crypt('ApexGrid2026!',gen_salt('bf',12)),'Driver '||lpad(n::text,2,'0'),'DRIVER'
FROM generate_series(1,10) n ON CONFLICT(email) DO NOTHING;
INSERT INTO teams(name,principal_user_id) VALUES
 ('Apex Racing',(SELECT id FROM users WHERE email='principal@apexgrid.test')),
 ('Northstar Motorsport',NULL),('Velocity Works',NULL),('Orion GP',NULL)
ON CONFLICT(name) DO NOTHING;
INSERT INTO drivers(user_id,licence_number,number)
SELECT u.id,format('AG-%s',lpad(n::text,4,'0')),n FROM generate_series(1,10) n
JOIN users u ON u.email=format('driver%s@apexgrid.test',lpad(n::text,2,'0'))
ON CONFLICT(licence_number) DO NOTHING;
INSERT INTO team_memberships(driver_id,team_id,start_date)
SELECT d.id,t.id,'2026-01-01'::date FROM drivers d
JOIN users u ON u.id=d.user_id
JOIN teams t ON t.name=CASE WHEN d.number<=3 THEN 'Apex Racing' WHEN d.number<=6 THEN 'Northstar Motorsport' WHEN d.number<=8 THEN 'Velocity Works' ELSE 'Orion GP' END
WHERE d.number BETWEEN 1 AND 10
AND d.licence_number=format('AG-%s',lpad(d.number::text,4,'0'))
AND NOT EXISTS(
 SELECT 1 FROM team_memberships m WHERE m.driver_id=d.id
 AND daterange(m.start_date,CASE WHEN m.end_date IS NULL THEN 'infinity'::date ELSE m.end_date+1 END,'[)')
     && daterange('2026-01-01'::date,'infinity'::date,'[)')
);
INSERT INTO championships(name,season) VALUES('ApexGrid World Series',2026) ON CONFLICT(name,season) DO NOTHING;
INSERT INTO circuits(name,country,length_km) VALUES
 ('Harbor Ring','Portugal',4.812),('Redwood International','United States',5.106),('Alpine Park','Austria',4.326)
ON CONFLICT(name) DO NOTHING;
INSERT INTO race_events(championship_id,circuit_id,round_number,name,start_date)
SELECT c.id,ci.id,x.round,x.event_name,x.start FROM championships c
JOIN (VALUES(1,'Lisbon Grand Prix','Harbor Ring','2026-03-15 14:00:00+00'::timestamptz),
            (2,'Redwood Grand Prix','Redwood International','2026-04-12 14:00:00+00'::timestamptz),
            (3,'Alpine Grand Prix','Alpine Park','2026-05-10 14:00:00+00'::timestamptz)) x(round,event_name,circuit_name,start)
 ON c.name='ApexGrid World Series' AND c.season=2026
JOIN circuits ci ON ci.name=x.circuit_name ON CONFLICT(championship_id,round_number) DO NOTHING;
INSERT INTO race_sessions(event_id,session_type,state,scheduled_at,started_at,ended_at,total_laps,safety_car)
SELECT e.id,st.session_type,st.state,e.start_date+st.offset_time,
 CASE WHEN st.state='COMPLETED' THEN e.start_date+st.offset_time+interval '1 hour' END,
 CASE WHEN st.state='COMPLETED' THEN e.start_date+st.offset_time+interval '2 hours' END,
 CASE WHEN st.session_type='RACE' THEN 25 ELSE 0 END,false
FROM race_events e JOIN championships c ON c.id=e.championship_id CROSS JOIN (VALUES
 ('PRACTICE'::session_type,'COMPLETED'::session_state,interval '-2 days'),
 ('QUALIFYING'::session_type,'COMPLETED'::session_state,interval '-1 day'),
 ('RACE'::session_type,'COMPLETED'::session_state,interval '0 days')) st(session_type,state,offset_time)
WHERE c.name='ApexGrid World Series' AND c.season=2026 AND e.round_number<=2
AND NOT EXISTS(SELECT 1 FROM race_sessions s WHERE s.event_id=e.id AND s.session_type=st.session_type);
-- Keep the next event ready for a live demo: scheduled race, no results yet.
INSERT INTO race_sessions(event_id,session_type,state,scheduled_at,total_laps,safety_car)
SELECT e.id,'RACE','SCHEDULED',e.start_date,25,false
FROM race_events e JOIN championships c ON c.id=e.championship_id
WHERE c.name='ApexGrid World Series' AND c.season=2026 AND e.round_number=3 AND NOT EXISTS(
 SELECT 1 FROM race_sessions s WHERE s.event_id=e.id AND s.session_type='RACE'
);
-- Completed historical race results; positions rotate by round, giving varied standings.
INSERT INTO session_results(session_id,driver_id,position,lap_time_ms,pole,fastest_lap,classified)
SELECT s.id,d.id,((d.number-1+e.round_number*3)%10)+1,85000+d.number*37,
 (d.number=1 AND e.round_number=1), (d.number=2 AND e.round_number=2),true
FROM race_sessions s JOIN race_events e ON e.id=s.event_id JOIN championships c ON c.id=e.championship_id CROSS JOIN drivers d
WHERE c.name='ApexGrid World Series' AND c.season=2026 AND s.session_type='RACE' AND e.round_number<=2
AND d.number BETWEEN 1 AND 10
AND s.scheduled_at=e.start_date
AND s.state='COMPLETED' AND s.started_at=s.scheduled_at+interval '1 hour'
AND s.ended_at=s.scheduled_at+interval '2 hours'
ON CONFLICT(session_id,driver_id) DO NOTHING;
INSERT INTO incident_reports(session_id,driver_id,lap,description,state,reported_at,decided_by,decision_notes)
SELECT s.id,d.id,8,'Unsafe rejoin after leaving the circuit','APPROVED',now()-interval '10 days',u.id,'Reviewed by race control'
FROM race_sessions s JOIN race_events e ON e.id=s.event_id JOIN championships c ON c.id=e.championship_id JOIN drivers d ON d.number=10
JOIN users u ON u.email='steward@apexgrid.test'
WHERE c.name='ApexGrid World Series' AND c.season=2026
AND s.session_type='RACE' AND e.round_number=1 AND s.scheduled_at=e.start_date
AND s.state='COMPLETED' AND s.started_at=s.scheduled_at+interval '1 hour'
AND s.ended_at=s.scheduled_at+interval '2 hours'
AND NOT EXISTS(SELECT 1 FROM incident_reports i WHERE i.session_id=s.id AND i.driver_id=d.id AND i.description='Unsafe rejoin after leaving the circuit');
INSERT INTO penalties(incident_id,driver_id,points,time_seconds,grid_places)
SELECT i.id,i.driver_id,3,5,0 FROM incident_reports i
JOIN race_sessions s ON s.id=i.session_id JOIN race_events e ON e.id=s.event_id
JOIN championships c ON c.id=e.championship_id
WHERE c.name='ApexGrid World Series' AND c.season=2026 AND e.round_number=1
AND s.scheduled_at=e.start_date AND s.state='COMPLETED'
AND s.started_at=s.scheduled_at+interval '1 hour' AND s.ended_at=s.scheduled_at+interval '2 hours'
AND i.description='Unsafe rejoin after leaving the circuit' ON CONFLICT(incident_id) DO NOTHING;
INSERT INTO pit_boxes(event_id,number)
SELECT e.id,n FROM race_events e JOIN championships c ON c.id=e.championship_id CROSS JOIN generate_series(1,4) n
WHERE c.name='ApexGrid World Series' AND c.season=2026
ON CONFLICT(event_id,number) DO NOTHING;
